screen.applet:
from enigma import getDesktop
deskwidth = getDesktop(0).size().width()
if deskwidth and deskwidth > 1920:
	f = 3
elif deskwidth and deskwidth > 1280:
	f = 1.5
else:
	f = 1
self['config'].l.setSeperation(int(300*f))

